import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"Plugin Examples","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. CoreExtensions —— Actions, Shell Menus & Quick Panel","slug":"_1-coreextensions-——-actions-shell-menus-quick-panel","link":"#_1-coreextensions-——-actions-shell-menus-quick-panel","children":[{"level":3,"title":"Key Implementation Highlights","slug":"key-implementation-highlights","link":"#key-implementation-highlights","children":[]}]},{"level":2,"title":"2. PinyinAlias —— Non-ASCII Transliteration Engine","slug":"_2-pinyinalias-——-non-ascii-transliteration-engine","link":"#_2-pinyinalias-——-non-ascii-transliteration-engine","children":[{"level":3,"title":"Key Implementation Highlights","slug":"key-implementation-highlights-1","link":"#key-implementation-highlights-1","children":[]}]},{"level":2,"title":"3. FlowLauncherBridge —— Cross-Ecosystem Compatibility & Isolated Runtimes","slug":"_3-flowlauncherbridge-——-cross-ecosystem-compatibility-isolated-runtimes","link":"#_3-flowlauncherbridge-——-cross-ecosystem-compatibility-isolated-runtimes","children":[{"level":3,"title":"Key Implementation Highlights","slug":"key-implementation-highlights-2","link":"#key-implementation-highlights-2","children":[]}]},{"level":2,"title":"4. FileUnlocker —— File occupation release action","slug":"_4-fileunlocker-——-file-occupation-release-action","link":"#_4-fileunlocker-——-file-occupation-release-action","children":[{"level":3,"title":"Key Implementation Highlights","slug":"key-implementation-highlights-3","link":"#key-implementation-highlights-3","children":[]}]}],"relativePath":"dev-guide/examples.md","filePath":"dev-guide/examples.md","lastUpdated":1791112464000}`),a={name:`dev-guide/examples.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plugin-examples" tabindex="-1">Plugin Examples <a class="header-anchor" href="#plugin-examples" aria-label="Permalink to “Plugin Examples”">​</a></h1><p>To help developers understand how <code>Lertaro.PluginSdk</code> interfaces cooperate in real-world scenarios, this chapter analyzes four representative open-source plugins included in the Lertaro repository.</p><h2 id="_1-coreextensions-——-actions-shell-menus-quick-panel" tabindex="-1">1. CoreExtensions —— Actions, Shell Menus &amp; Quick Panel <a class="header-anchor" href="#_1-coreextensions-——-actions-shell-menus-quick-panel" aria-label="Permalink to “1. CoreExtensions —— Actions, Shell Menus &amp; Quick Panel”">​</a></h2><p>The <code>CoreExtensions</code> plugin is Lertaro&#39;s core functionality bundle, implementing <code>IPlugin</code>, <code>IActionProvider</code>, <code>IConfigurable</code>, and multiple sub-providers.</p><h3 id="key-implementation-highlights" tabindex="-1">Key Implementation Highlights <a class="header-anchor" href="#key-implementation-highlights" aria-label="Permalink to “Key Implementation Highlights”">​</a></h3><ul><li><strong>Static Result Actions (<code>IActionProvider.GetActions()</code>)</strong>: Exposes the core file actions, including opening and locating items, copying paths and files, adding a result to Favorites, renaming items, shell commands, deletion, and administrator variants.</li><li><strong>Native Shell Menu Integration (<code>IDynamicActionProvider</code>)</strong>: Interacts with Windows Shell COM interfaces via <code>ShellMenuActionProvider</code>, rendering full Windows context menus (with cascading submenus like &quot;Send to&quot;, 7-Zip, VS Code) directly inside Lertaro&#39;s <code>Ctrl+O</code> action menu.</li><li><strong>Schema-Driven Configuration Forms (<code>IConfigurable</code>)</strong>: Demonstrates defining configuration schemas with nested groups (<code>Group</code>), string lists (<code>StringList</code>), and hotkey recorders (<code>Hotkey</code>), rendering native UI forms in Settings without custom XAML.</li><li><strong>Diverse Quick Panel Tabs (<code>IQuickPanelTabProvider</code>)</strong>: <ul><li><code>FavoritesTabProvider</code> / <code>HistoryTabProvider</code>: serve the host&#39;s already-loaded favorites and history rather than re-reading them from disk; the history query is dispatched off the UI thread (<code>Task.Run</code>), so summoning the panel never waits on it.</li><li><code>WindowsRecentTabProvider</code>: Crawls the Windows <code>Recent</code> folder on a background thread, resolves COM shortcut targets, truncates results, and populates <code>Metadata.Modified</code> for accurate sorting.</li><li><code>LastDirectoryTabProvider</code> / <code>RecentFilesTabProvider</code>: Directly queries the host&#39;s <a href="./sdk/services.html"><code>ExplorerPathService</code></a> and <code>RecentFilesService</code>.</li></ul></li></ul><h2 id="_2-pinyinalias-——-non-ascii-transliteration-engine" tabindex="-1">2. PinyinAlias —— Non-ASCII Transliteration Engine <a class="header-anchor" href="#_2-pinyinalias-——-non-ascii-transliteration-engine" aria-label="Permalink to “2. PinyinAlias —— Non-ASCII Transliteration Engine”">​</a></h2><p>The <code>PinyinAlias</code> plugin provides full pinyin and initialism alias search support for Chinese filenames, implementing both <code>IAliasProvider</code> and <code>ITranslationProvider</code>.</p><h3 id="key-implementation-highlights-1" tabindex="-1">Key Implementation Highlights <a class="header-anchor" href="#key-implementation-highlights-1" aria-label="Permalink to “Key Implementation Highlights”">​</a></h3><ul><li><strong>Alphabet Boundaries (<code>InputRanges</code> / <code>OutputRanges</code>)</strong>: Declares one CJK Ideograph range (U+3007–U+9FFD) as the input boundary and lowercase <code>a</code>–<code>z</code> as the output range. The host uses these boundaries to partition mixed queries (e.g. <code>大cj</code> matching <code>大长今</code>) into literal and alias segments.</li><li><strong>Pre-flight Fast Checks (<code>CanHandle(text)</code>)</strong>: Scans for Chinese characters before generating aliases, returning <code>false</code> immediately for pure English strings to avoid allocation overhead.</li><li><strong>Polyphonic Combinations (<code>GetAliases(text)</code>)</strong>: Constructs a syllable map and generates all common pronunciation combinations connected with <code>|</code> (capped at 32 combinations to prevent combinatorial explosions), allowing parallel matching across all permutations.</li><li><strong>Embedded Localization &amp; Thread-Safe Caching</strong>: Provides localized plugin display names via <code>ITranslationProvider</code>, caching parsed JSON tables inside a <code>lock</code>-guarded dictionary to avoid repeated disk reads.</li></ul><h2 id="_3-flowlauncherbridge-——-cross-ecosystem-compatibility-isolated-runtimes" tabindex="-1">3. FlowLauncherBridge —— Cross-Ecosystem Compatibility &amp; Isolated Runtimes <a class="header-anchor" href="#_3-flowlauncherbridge-——-cross-ecosystem-compatibility-isolated-runtimes" aria-label="Permalink to “3. FlowLauncherBridge —— Cross-Ecosystem Compatibility &amp; Isolated Runtimes”">​</a></h2><p>The <code>FlowLauncherBridge</code> plugin demonstrates building a large-scale bridge system to integrate external community ecosystems into Lertaro.</p><h3 id="key-implementation-highlights-2" tabindex="-1">Key Implementation Highlights <a class="header-anchor" href="#key-implementation-highlights-2" aria-label="Permalink to “Key Implementation Highlights”">​</a></h3><ul><li><strong>Multi-Language IPC Bridge</strong>: Runs Flow Launcher plugins written in C# (.NET), Python 3.12, Node.js v20 LTS, and standalone executables (<code>.exe</code>).</li><li><strong>Isolated Self-Contained Runtimes</strong>: Deploys isolated Python and Node.js runtimes under Lertaro&#39;s <strong>shared data directory</strong> (<code>SharedDataDirectory\\FlowData\\PythonEmbeded-{arch}</code>), not the per-user data folder. Each plugin talks to its interpreter over <strong>redirected standard input/output</strong> carrying JSON-RPC — there is no named pipe, and the system PATH is never touched.</li><li><strong>Dynamic Configuration &amp; WebView2 Previews</strong>: Dynamically maps external <code>SettingsTemplate.yaml</code>/<code>.json</code> forms to <code>PluginConfigSchema</code>, and renders rich interactive HTML/WebView2 previews (e.g. MDict definitions, weather cards) inside QuickLook.</li></ul><h2 id="_4-fileunlocker-——-file-occupation-release-action" tabindex="-1">4. FileUnlocker —— File occupation release action <a class="header-anchor" href="#_4-fileunlocker-——-file-occupation-release-action" aria-label="Permalink to “4. FileUnlocker —— File occupation release action”">​</a></h2><p><code>FileUnlocker</code> demonstrates a focused action plugin that uses the Windows Restart Manager API through a small client wrapper.</p><h3 id="key-implementation-highlights-3" tabindex="-1">Key Implementation Highlights <a class="header-anchor" href="#key-implementation-highlights-3" aria-label="Permalink to “Key Implementation Highlights”">​</a></h3><ul><li><strong>Single-selection guard</strong>: The action is offered only for one existing file, avoiding ambiguous requests against folders or multiple results.</li><li><strong>Process inspection</strong>: It displays the locking process name, PID, and executable path, with a refresh operation for changing file state.</li><li><strong>Request-based release</strong>: The plugin asks the owning processes to release the file and disables the release button while no process is detected or an operation is running.</li><li><strong>Host-owned window frame</strong>: Its WPF view is placed in the SDK&#39;s themed <code>PluginWindow</code> dialog, so the plugin does not duplicate theme, DPI, taskbar, or Alt+Tab handling.</li></ul>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};